// Raw pointer stream — every move, no arena, no delay.
Listener(
  behavior: HitTestBehavior.opaque,
  onPointerDown: (e) => _strokes.add(Stroke(e.localPosition)),
  onPointerMove: (e) => _strokes.last.extend(e.localPosition),
  onPointerUp: (e) => _commit(),
  onPointerCancel: (e) => _discard(),   // the OS took the pointer away
  child: CustomPaint(painter: InkPainter(_strokes)),
);

// Recognized gestures — the arena decides who gets the sequence.
GestureDetector(
  onTap: _open,                            // fires only after this detector wins
  onLongPress: _showMenu,
  onHorizontalDragUpdate: (d) => _slide(d.delta.dx),
  child: const RowCard(),
);

// A tap hand-rolled on Listener: no slop, no cancel, no semantics
Listener(
  onPointerUp: (_) => _open(),  // fires even if the finger dragged 200 px away
  child: const RowCard(),
);

// Let the recognizer do it, and keep Listener for what only it can see
GestureDetector(onTap: _open, child: const RowCard());

// Hover and cursor are neither of the two
MouseRegion(
  cursor: SystemMouseCursors.click,
  onEnter: (_) => setState(() => _hovered = true),
  onExit: (_) => setState(() => _hovered = false),
  child: const RowCard(),
);

// Feedback on down, commit on win, undo on loss — how a button really behaves.
class PressableCard extends StatefulWidget {
  const PressableCard({super.key, required this.onOpen, required this.child});
  final VoidCallback onOpen;
  final Widget child;

  @override
  State<PressableCard> createState() => _PressableCardState();
}

class _PressableCardState extends State<PressableCard> {
  bool _pressed = false;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTapDown: (_) => setState(() => _pressed = true),    // before the arena resolves
      onTapCancel: () => setState(() => _pressed = false),  // the scrollable stole it
      onTapUp: (_) => setState(() => _pressed = false),
      onTap: widget.onOpen,                                 // only after winning
      child: AnimatedScale(
        scale: _pressed ? 0.97 : 1,
        duration: const Duration(milliseconds: 90),
        child: widget.child,
      ),
    );
  }
}

