// Throws: "Having both a pan gesture recognizer and a scale gesture recognizer
// is redundant; scale is a superset of pan."
GestureDetector(
  onPanUpdate: (d) => _pan(d.delta),
  onScaleUpdate: (d) => _zoom(d.scale),
  child: const MapSurface(),
