// One scale recognizer covers both. Capture the baseline at the start,
// because details.scale is relative to the gesture, not to the last frame.
class _MapState extends State<MapView> {
  Offset _offset = Offset.zero;
  double _scale = 1;
  Offset _baseOffset = Offset.zero;
  double _baseScale = 1;

  void _onStart(ScaleStartDetails d) {
    _baseOffset = _offset;
    _baseScale = _scale;
  }

  void _onUpdate(ScaleUpdateDetails d) {
    setState(() {
      _scale = (_baseScale * d.scale).clamp(1.0, 8.0);  // not _scale * d.scale
      _offset = _baseOffset + d.focalPointDelta;        // the pan half
      if (d.pointerCount == 1) _scale = _baseScale;     // one finger never zooms
    });
  }

  @override
  Widget build(BuildContext context) => GestureDetector(
        onScaleStart: _onStart,
        onScaleUpdate: _onUpdate,
        child: Transform(
          transform: Matrix4.identity()
            ..translate(_offset.dx, _offset.dy)
            ..scale(_scale),
          child: const MapSurface(),
        ),
      );
}

// Stock recognizers, configured the way GestureDetector will not let you.
RawGestureDetector(
  behavior: HitTestBehavior.opaque,
  gestures: <Type, GestureRecognizerFactory>{
    LongPressGestureRecognizer:
        GestureRecognizerFactoryWithHandlers<LongPressGestureRecognizer>(
      () => LongPressGestureRecognizer(
        duration: const Duration(milliseconds: 200),   // not the 500 ms default
      ),
      (instance) => instance.onLongPress = _showMenu,
    ),
    TapGestureRecognizer: GestureRecognizerFactoryWithHandlers<TapGestureRecognizer>(
      () => TapGestureRecognizer(
        supportedDevices: const {PointerDeviceKind.stylus},   // pen only
      ),
      (instance) => instance.onTap = _annotate,
    ),
  },
  child: const DrawingSurface(),
);

// A recognizer of your own: claim the sequence as soon as two fingers are down.
class TwoFingerPanRecognizer extends OneSequenceGestureRecognizer {
  TwoFingerPanRecognizer({this.onPan});

  final ValueChanged<Offset>? onPan;
  final Map<int, Offset> _down = <int, Offset>{};

  @override
  void addAllowedPointer(PointerDownEvent event) {
    startTrackingPointer(event.pointer, event.transform);
    _down[event.pointer] = event.position;
    if (_down.length == 2) resolve(GestureDisposition.accepted);
  }

  @override
  void handleEvent(PointerEvent event) {
    if (event is PointerMoveEvent && _down.length == 2) {
      onPan?.call(event.delta);
    } else if (event is PointerUpEvent || event is PointerCancelEvent) {
      _down.remove(event.pointer);
      stopTrackingPointer(event.pointer);
    }
  }

  @override
  void didStopTrackingLastPointer(int pointer) => _down.clear();

  @override
  String get debugDescription => 'two-finger pan';
}

