// Identity key, data removed in the same frame, row state hoisted into the list.
ListView.builder(
  itemCount: tasks.length,
  itemBuilder: (context, i) {
    final task = tasks[i];
    return Dismissible(
      key: ValueKey(task.id),
      direction: DismissDirection.endToStart,
      background: const ArchiveBackground(),
      confirmDismiss: (_) async {
        if (!task.hasUnsavedEdits) return true;
        return await _askDiscard(context) ?? false;   // null cancels too
      },
      onDismissed: (_) {
        final removed = task;                          // keep it for undo
        setState(() => tasks.remove(task));
        _showUndoBar(onUndo: () => setState(() => tasks.insert(i, removed)));
      },
      child: TaskRow(
        task: task,
        expanded: _expandedIds.contains(task.id),      // state lives in the list
        onToggle: () => setState(() {
          if (!_expandedIds.remove(task.id)) _expandedIds.add(task.id);
        }),
      ),
    );
  },
);

class _ZoomableState extends State<Zoomable> with SingleTickerProviderStateMixin {
  final TransformationController _transform = TransformationController();
  late final AnimationController _anim = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 250),
  )..addListener(() => _transform.value = _zoom!.value);

  Animation<Matrix4>? _zoom;
  Offset _tap = Offset.zero;

  @override
  void dispose() {
    _anim.dispose();
    _transform.dispose();
    super.dispose();
  }

  // Keep the tapped content point under the finger: v = scale * scene + t
  Matrix4 _matrixFor(double scale) {
    final scene = _transform.toScene(_tap);
    return Matrix4.identity()
      ..translate(_tap.dx - scale * scene.dx, _tap.dy - scale * scene.dy)
      ..scale(scale);
  }

  void _handleDoubleTap() {
    final zoomedIn = _transform.value.getMaxScaleOnAxis() > 1.5;
    _zoom = Matrix4Tween(begin: _transform.value, end: _matrixFor(zoomedIn ? 1.0 : 2.5))
        .animate(CurvedAnimation(parent: _anim, curve: Curves.easeOut));
    _anim.forward(from: 0);
  }

  @override
  Widget build(BuildContext context) => GestureDetector(
        onDoubleTapDown: (d) => _tap = d.localPosition,   // onDoubleTap has no details
        onDoubleTap: _handleDoubleTap,
        child: InteractiveViewer(
          transformationController: _transform,
          minScale: 1,
          maxScale: 4,
          boundaryMargin: const EdgeInsets.all(double.infinity),
          onInteractionStart: (_) => _anim.stop(),        // the finger wins immediately
          child: Image.asset(widget.path),
        ),
      );
}

// Velocity alone: a slow drag that stops before the lift reports 0 and never commits.
onHorizontalDragEnd: (d) {
  if (d.primaryVelocity!.abs() > 300) _delete();
},

// Raw pixels/second into a 0..1 controller: the card teleports.
_controller.fling(velocity: d.velocity.pixelsPerSecond.dx);

// Distance OR fling decides; then the velocity is converted into the target's units.
class _SwipeRowState extends State<SwipeRow> with SingleTickerProviderStateMixin {
  static const double _width = 320;
  static const SpringDescription _spring =
      SpringDescription(mass: 1, stiffness: 500, damping: 30);

  late final AnimationController _c = AnimationController(vsync: this);
  double _dx = 0;

  void _onUpdate(DragUpdateDetails d) => setState(() => _dx += d.delta.dx);

  void _onEnd(DragEndDetails d) {
    final pixelsPerSecond = d.primaryVelocity ?? 0;      // exactly 0 if not a fling
    final flung = pixelsPerSecond.abs() > kMinFlingVelocity;
    final commit = flung ? pixelsPerSecond < 0 : _dx < -_width * 0.4;

    _c.animateWith(SpringSimulation(
      _spring,
      _c.value,
      commit ? 1.0 : 0.0,
      pixelsPerSecond.abs() / _width,                    // px/s -> value/s
    ));
  }

  @override
  Widget build(BuildContext context) => GestureDetector(
        onHorizontalDragUpdate: _onUpdate,
        onHorizontalDragEnd: _onEnd,                     // never onPanEnd: no primary axis
        child: widget.child,
      );
}

// Wheel and trackpad arrive outside the arena: a Listener sees them, gestures do not.
Listener(
  onPointerSignal: (event) {
    if (event is! PointerScrollEvent) return;
    // Register, or the ListView behind you zooms and scrolls on the same tick.
    GestureBinding.instance.pointerSignalResolver.register(event, (e) {
      final scroll = e as PointerScrollEvent;
      setState(() => _scale = (_scale - scroll.scrollDelta.dy / 500).clamp(0.5, 4.0));
    });
  },
  // macOS trackpad: a real gesture with scale and rotation, not a scroll
  onPointerPanZoomStart: (_) => _baseScale = _scale,
  onPointerPanZoomUpdate: (e) => setState(() => _scale = _baseScale * e.scale),
  child: const CanvasSurface(),
);

// Hover is not a pointer move — Listener never sees it.
MouseRegion(
  cursor: SystemMouseCursors.precise,
  onHover: (e) => setState(() => _crosshair = e.localPosition),
  onExit: (_) => setState(() => _crosshair = null),
  child: const CanvasSurface(),
);

// Pressure only means something for a pen; touch reports a constant.
Listener(
  onPointerMove: (e) {
    final pressure = e.kind == PointerDeviceKind.stylus
        ? (e.pressure - e.pressureMin) / (e.pressureMax - e.pressureMin)
        : 0.5;
    _stroke.add(e.localPosition, pressure);
  },
  child: const CanvasSurface(),
);

// "The wheel should zoom, not scroll" is one flag.
InteractiveViewer(
  trackpadScrollCausesScale: true,
  child: const Diagram(),
);

import 'package:flutter/services.dart';

class SaveIntent extends Intent {
  const SaveIntent();
}

Widget buildEditor(BuildContext context) {
  return Shortcuts(
    shortcuts: <ShortcutActivator, Intent>{
      // Cmd on macOS, Ctrl elsewhere — bind both instead of branching later
      const SingleActivator(LogicalKeyboardKey.keyS, control: true): const SaveIntent(),
      const SingleActivator(LogicalKeyboardKey.keyS, meta: true): const SaveIntent(),
    },
    child: Actions(
      actions: <Type, Action<Intent>>{
        SaveIntent: CallbackAction<SaveIntent>(onInvoke: (_) => _save()),
      },
      child: Focus(
        autofocus: true,             // no focus in this subtree = no shortcut, ever
        child: Column(
          children: [
            Builder(                 // look Actions up from BELOW the Actions widget
              builder: (context) => IconButton(
                onPressed: () => Actions.maybeInvoke(context, const SaveIntent()),
                icon: const Icon(Icons.save),
              ),
            ),
            const Expanded(child: NoteEditor()),
          ],
        ),
      ),
    ),
  );
}

// A modifier held during a click is not a shortcut: ask the keyboard directly.
GestureDetector(
  onTapUp: (_) {
    final keyboard = HardwareKeyboard.instance;
    setState(() {
      if (keyboard.isShiftPressed) {
        _selectRangeTo(index);
      } else if (keyboard.isMetaPressed || keyboard.isControlPressed) {
        _toggle(index);
      } else {
        _selectOnly(index);
