// Pointer-only: with a screen reader on, no PointerEvent ever arrives here.
Listener(
  onPointerMove: (e) => _setBrightness(e.localPosition.dx / _width),
  child: const BrightnessBar(),
);

// The same control, described as the slider it is.
Semantics(
  slider: true,
  label: 'Brightness',
  value: '${(_value * 100).round()}%',
  onIncrease: () => _setBrightness((_value + 0.1).clamp(0, 1)),
  onDecrease: () => _setBrightness((_value - 0.1).clamp(0, 1)),
  child: ExcludeSemantics(              // the painted internals add nothing
    child: GestureDetector(
      onHorizontalDragUpdate: (d) => _setBrightness(_value + d.delta.dx / _width),
      child: const BrightnessBar(),
    ),
  ),
);

// A swipe has no standard semantic action, so give it a named one.
Semantics(
  container: true,
  label: message.subject,
  customSemanticsActions: <CustomSemanticsAction, VoidCallback>{
    const CustomSemanticsAction(label: 'Archive'): () => _archive(message),
    const CustomSemanticsAction(label: 'Mark unread'): () => _markUnread(message),
  },
  child: Dismissible(
    key: ValueKey(message.id),
    onDismissed: (_) => _archive(message),
    child: MessageRow(message: message),
  ),
);

// Nothing visible moved after the action — say it out loud.
void _archive(Message m) {
  _inbox.archive(m);
  SemanticsService.announce('Archived', Directionality.of(context));
}

